import boto3
from datetime import datetime, timedelta, timezone


def tagged_groups(ec, key, value):
    groups = []
    for page in ec.get_paginator('describe_replication_groups').paginate():
        for rg in page['ReplicationGroups']:
            tags = ec.list_tags_for_resource(ResourceName=rg['ARN']).get('TagList', [])
            if any(t['Key'] == key and t['Value'] == value for t in tags):
                groups.append(rg)
    return groups


def trigger_failover(events, context):
    ec = boto3.client('elasticache', region_name=events['region'])
    start = (datetime.now(timezone.utc) - timedelta(seconds=10)).isoformat()
    groups = tagged_groups(ec, events['tagKey'], events['tagValue'])
    if not groups:
        raise Exception('No replication group found with tag {}={}'.format(events['tagKey'], events['tagValue']))
    not_ready = ['{} (status {}, AutomaticFailover {})'.format(g['ReplicationGroupId'], g['Status'], g.get('AutomaticFailover')) for g in groups if g['Status'] != 'available' or g.get('AutomaticFailover') != 'enabled']
    if not_ready:
        raise Exception('Tagged replication groups not ready for failover: ' + ', '.join(not_ready))
    for g in groups:
        node_group = g['NodeGroups'][0]['NodeGroupId']
        ec.test_failover(ReplicationGroupId=g['ReplicationGroupId'], NodeGroupId=node_group)
        print('TestFailover called for {} node group {}'.format(g['ReplicationGroupId'], node_group))
    return {'ReplicationGroupIds': ','.join(g['ReplicationGroupId'] for g in groups), 'StartTime': start}

import time
from datetime import datetime

import boto3


def problems(ec, rg_id):
    g = ec.describe_replication_groups(ReplicationGroupId=rg_id)['ReplicationGroups'][0]
    out = []
    if g['Status'] != 'available':
        out.append('group status ' + g['Status'])
    for ng in g['NodeGroups']:
        n = sum(1 for m in ng['NodeGroupMembers'] if m.get('CurrentRole') == 'primary')
        if n != 1:
            out.append('node group {} has {} primaries'.format(ng['NodeGroupId'], n))
    for cid in g.get('MemberClusters', []):
        status = ec.describe_cache_clusters(CacheClusterId=cid)['CacheClusters'][0]['CacheClusterStatus']
        if status != 'available':
            out.append('cluster {} status {}'.format(cid, status))
    return out


def wait_for_failover(events, context):
    ec = boto3.client('elasticache', region_name=events['region'])
    start = datetime.fromisoformat(events['startTime'])
    groups = [x for x in events['replicationGroupIds'].split(',') if x]
    deadline = time.time() + int(events['timeoutSeconds'])
    while True:
        waiting = {}
        for rg_id in groups:
            messages = [e['Message'] for e in ec.describe_events(SourceIdentifier=rg_id, SourceType='replication-group', StartTime=start)['Events']]
            if not any(m.startswith('Failover from') and 'completed' in m for m in messages):
                waiting[rg_id] = 'failover not completed yet'
                continue
            issues = problems(ec, rg_id)
            if issues:
                waiting[rg_id] = '; '.join(issues)
        if not waiting:
            print('Failover completed for ' + ', '.join(groups))
            return {'Status': 'failover completed'}
        if time.time() > deadline:
            raise Exception('Failover did not complete in time: ' + str(waiting))
        time.sleep(10)

import time
from datetime import datetime

import boto3


def in_progress(ec, rg_id, since, need_call):
    g = ec.describe_replication_groups(ReplicationGroupId=rg_id)['ReplicationGroups'][0]
    found = []
    for source, kind in [(rg_id, 'replication-group')] + [(c, 'cache-cluster') for c in g.get('MemberClusters', [])]:
        found += ec.describe_events(SourceIdentifier=source, SourceType=kind, StartTime=since)['Events']
    state = 'no TestFailover call event yet' if need_call else None
    for e in sorted(found, key=lambda e: e['Date']):
        m = e['Message']
        if m.startswith('Test Failover API called'):
            state = 'failover in progress'
        elif m.startswith('Failover from') and 'completed' in m:
            state = 'former primary recovery pending'
        elif m.startswith('Recovering cache nodes'):
            state = 'former primary recovering'
        elif m.startswith('Finished recovery for cache nodes') and state != 'no TestFailover call event yet':
            state = None
    return state


def wait_for_recovery(events, context):
    ec = boto3.client('elasticache', region_name=events['region'])
    start = datetime.fromisoformat(events['startTime'])
    groups = [x for x in events['replicationGroupIds'].split(',') if x]
    deadline = time.time() + int(events['timeoutSeconds'])
    while True:
        waiting = {}
        for rg_id in groups:
            state = in_progress(ec, rg_id, start, True)
            if state:
                waiting[rg_id] = state
        if not waiting:
            print('Former primary recovered for ' + ', '.join(groups))
            return {'Status': 'recovered'}
        if time.time() > deadline:
            if events['failIfNotDone'] == 'true':
                raise Exception('Node recovery did not finish in time: ' + str(waiting))
            print('Still recovering, continuing in the next step: ' + str(waiting))
            return {'Status': 'still recovering'}
        time.sleep(15)

