def verify_healthy(events, context):
    ec = boto3.client('elasticache', region_name=events['region'])
    deadline = time.time() + int(events['timeoutSeconds'])
    healthy_since = None
    while True:
        since = datetime.now(timezone.utc) - timedelta(minutes=60)
        bad = {}
        for g in tagged_groups(ec, events['tagKey'], events['tagValue']):
            rg_id = g['ReplicationGroupId']
            issues = problems(ec, rg_id)
            state = in_progress(ec, rg_id, since)
            if state:
                issues.append(state)
            if issues:
                bad[rg_id] = issues
        if bad:
            healthy_since = None
        elif healthy_since is None:
            healthy_since = time.time()
        if healthy_since is not None and time.time() - healthy_since >= 30:
            print('All tagged replication groups are healthy')
            return {'Status': 'healthy'}
        if time.time() > deadline:
            if not bad:
                print('All tagged replication groups are healthy')
                return {'Status': 'healthy'}
            message = 'Not healthy yet: ' + str(bad) + '. A started failover cannot be undone; ElastiCache completes it on its own.'
            print(message)
            return {'Status': message}
        time.sleep(10)
